**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
using namespace std;

int iloczynCyfr(int n) {
    int il = 1;
    while (n > 0) {
        il *= n % 10;
        n /= 10;
    }
    return il;
}

int main() {
    ifstream plik("dane.txt");
    int liczba;
    vector<int> liczby, iloczyny;
    while (plik >> liczba) {
        liczby.push_back(liczba);
        iloczyny.push_back(iloczynCyfr(liczba));
    }

    cout << "a) Iloczyny cyfr:" << endl;
    for (int i = 0; i < (int)liczby.size(); i++) {
        string s = to_string(liczby[i]);
        cout << liczby[i] << ": ";
        for (int j = 0; j < (int)s.length(); j++) {
            if (j > 0) cout << "*";
            cout << s[j];
        }
        cout << " = " << iloczyny[i] << endl;
    }

    cout << endl << "b) Iloczyn cyfr podzielny przez 6:" << endl;
    int ile = 0;
    for (int i = 0; i < (int)liczby.size(); i++) {
        if (iloczyny[i] % 6 == 0) {
            cout << liczby[i] << " (iloczyn " << iloczyny[i] << ")" << endl;
            ile++;
        }
    }
    cout << "Ilosc: " << ile << endl;

    cout << endl << "c) Najwiekszy iloczyn cyfr: ";
    int maxIdx = 0;
    for (int i = 1; i < (int)liczby.size(); i++) {
        if (iloczyny[i] > iloczyny[maxIdx]) maxIdx = i;
    }
    cout << liczby[maxIdx] << " (iloczyn " << iloczyny[maxIdx] << ")" << endl;
    return 0;
}
```

**Wyjasnienie**: Iloczyn cyfr obliczany analogicznie do sumy, ale z mnozeniem (start od 1). Jesli liczba zawiera cyfre 0, iloczyn = 0, a 0 % 6 == 0 wiec taka liczba spelnia warunek podzielnosci.

